import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import {
  getGoldAttributeValues,
  _resetGoldAttributesCacheForTest,
} from './gold-attributes-lookup';

// These tests exercise the DEFAULT (frozen-fixture) source path only — no DB.
// The fixture is the committed P0 snapshot generated by snapshot-gold-attributes.ts.

describe('getGoldAttributeValues — frozen fixture (default source, no DB)', () => {
  beforeEach(() => {
    delete process.env.GOLD_ATTR_SOURCE; // ensure default (frozen) source
    _resetGoldAttributesCacheForTest();
  });
  afterEach(() => {
    _resetGoldAttributesCacheForTest();
  });

  it('reads a known code+attribute array from the frozen snapshot', async () => {
    // 0101.21.00 is the first row in the snapshot (pure-bred breeding horses).
    const material = await getGoldAttributeValues('0101.21.00', 'material');
    expect(material).toEqual(['horse']);
  });

  it('maps the `function` attribute to the function_ column', async () => {
    const fn = await getGoldAttributeValues('0101.21.00', 'function');
    expect(fn).toEqual(['breeding-stock']);
  });

  it('returns null for an empty array column (no answer available)', async () => {
    // composition is [] for 0101.21.00 → treated as unanswerable (null).
    const comp = await getGoldAttributeValues('0101.21.00', 'composition');
    expect(comp).toBeNull();
  });

  it('returns null for a code absent from the snapshot', async () => {
    const v = await getGoldAttributeValues('9999.99.99', 'material');
    expect(v).toBeNull();
  });

  it('caches per code (repeat lookup returns the same value without DB)', async () => {
    const a = await getGoldAttributeValues('0101.21.00', 'form');
    const b = await getGoldAttributeValues('0101.21.00', 'processing_state');
    expect(a).toEqual(['live-animal']);
    expect(b).toEqual(['live', 'pure-bred']);
  });
});
